import{_ as e,o as s,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"大东","description":"","frontmatter":{"title":"大东","date":"2026-11-08T00:00:00.000Z","seq":43,"categories":["美文","诗经"],"collection":"《诗经 · 小雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·小雅/大东.md","filePath":"blogs/诗经·小雅/大东.md"}'),p={name:"blogs/诗经·小雅/大东.md"};function c(l,a,r,n,_,m){return s(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="大东" tabindex="-1">大东 <a class="header-anchor" href="#大东" aria-label="Permalink to &quot;大东&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　小雅 · 谷风之什</p><div class="poem"><p class="poem-stanza">有饛簋飧，有捄棘匕。周道如砥，其直如矢。君子所履，小人所视。眷言顾之，潸焉出涕。</p><p class="poem-stanza">小东大东，杼柚其空。纠纠葛屦，可以履霜。佻佻公子，行彼周行。既往既来，使我心疚。</p><p class="poem-stanza">有冽氿泉，无浸获薪。契契寤叹，哀我惮人。薪是获薪，尚可载也。哀我惮人，亦可息也。</p><p class="poem-stanza">东人之子，职劳不来。西人之子，粲粲衣服。舟人之子，熊罴是裘。私人之子，百僚是试。</p><p class="poem-stanza">或以其酒，不以其浆。鞙鞙佩璲，不以其长。维天有汉，监亦有光。跂彼织女，终日七襄。</p><p class="poem-stanza">虽则七襄，不成报章。睆彼牵牛，不以服箱。东有启明，西有长庚。有捄天毕，载施之行。</p><p class="poem-stanza">维南有箕，不可以簸扬。维北有斗，不可以挹酒浆。维南有箕，载翕其舌。维北有斗，西柄之揭。</p></div>',3)])])}const u=e(p,[["render",c]]);export{d as __pageData,u as default};
